-- Newsletter becomes opt-in (Oct 2026): everybody starts switched off.
-- 1) Switch every existing user off. Users can turn it back on in Profile -> Settings.
UPDATE "User" SET "newsletterOptIn" = false;

-- 2) Column default true -> false (generated by `prisma migrate diff`; SQLite needs a table rebuild).
-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_User" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT,
    "username" TEXT,
    "email" TEXT,
    "emailVerified" DATETIME,
    "image" TEXT,
    "bio" TEXT,
    "passwordHash" TEXT,
    "role" TEXT NOT NULL DEFAULT 'user',
    "bannedAt" DATETIME,
    "banReason" TEXT,
    "supporterAt" DATETIME,
    "newsletterOptIn" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "new_User" ("banReason", "bannedAt", "bio", "createdAt", "email", "emailVerified", "id", "image", "name", "newsletterOptIn", "passwordHash", "role", "supporterAt", "username") SELECT "banReason", "bannedAt", "bio", "createdAt", "email", "emailVerified", "id", "image", "name", "newsletterOptIn", "passwordHash", "role", "supporterAt", "username" FROM "User";
DROP TABLE "User";
ALTER TABLE "new_User" RENAME TO "User";
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;
